// Caller says which commit it deployed; the API says which commit it is
// running. Anything other than an exact match is a failed deploy — including
// the case where the container is perfectly healthy and simply old, which is
// the failure a liveness check cannot see.
const want = ($('Webhook /deploy-verify').first().json.body || {}).commit || '';
const env = ($('Webhook /deploy-verify').first().json.body || {}).env || 'uat';
const res = $input.first().json;

if (res.error || !res.commit) {
  return [{ json: {
    ok: false,
    text: `❌ Certifine ${env}: 攞唔到 build stamp（${res.error || 'no commit field'}）。`,
  }}];
}

const ok = !!want && res.commit === want;
const short = (c) => String(c).slice(0, 8);
return [{ json: {
  ok,
  env,
  want,
  got: res.commit,
  builtAt: res.builtAt,
  text: ok
    ? `✅ Certifine ${env} deploy 生效：${short(res.commit)}（built ${res.builtAt}）`
    : `❌ Certifine ${env} deploy 未生效：行緊 ${short(res.commit)}，應該係 ${short(want) || '(caller 冇畀 commit)'}。`,
}}];
